def compass_detail(n, page):
    """One COMPASS domain panel. The teaching text is the same on both pages; the question keeps each page's own framing."""
    c = COMPASS[n]
    q = ('<div class="cm-q">&#10148; ' + c['pq'] + '</div>') if page == 'p' else ('<div class="cm-action">&#10148; Facilitation question: ' + c['fq'] + '</div>')
    return ('  <div id="cm%d" class="cm-detail"><div class="cm-col"><h5>The Signal Narrative</h5>' % n + ''.join('<p>%s</p>' % x for x in c['narr']) +
            '</div><div class="cm-col"><h5>Observable Indicators</h5><p>' + c['ind'] + '</p><div class="cm-signal">' + c['signal'] + '</div>' + q + '</div></div>\n')

def role_detail(n, page):
    r = ROLES_F[n]
    a, b = (ROLES_P[n] if page == 'p' else (r['f_contrib'], r['f_absent']))
    return ('  <div id="rl%d" class="rl-detail"><div class="rl-col"><h5>Converging Zone Contribution</h5><p>' % n + a + '</p></div><div class="rl-col"><h5>Primary COMPASS Activation</h5>'
            '<div class="rl-domains">' + r['domains'] + '</div><p style="margin-top:12px;font-size:12px;color:rgba(255,255,255,.5);">' + b + '</p></div></div>\n')

